function update2DAvatar(host){host.querySelector('.premium-portrait')?.remove();host.insertAdjacentHTML('afterbegin',premiumPortraitMarkup());S.avatarReady=true;valid()}
function bindLiveAppearance(root){const controls=root.querySelector('.avatar-controls');if(!controls)return;controls.addEventListener('click',e=>{const button=e.target.closest('button[data-look]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const key=button.dataset.look,value=button.dataset.value;if(!key||value==null)return;S[key]=value;button.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===button));root.querySelectorAll('[data-avatar2d]').forEach(update2DAvatar);const status=root.querySelector('.avatar-name');if(status){status.classList.remove('changed');void status.offsetWidth;status.classList.add('changed');status.innerHTML=`<i></i>${S.name} · MODIFICA APPLICATA ✓`}},true)}
